    fromRow: r => ({ id:r.id, name:r.name, model:r.model||'', sku:r.sku||'', category:r.category||'', unit:r.unit||'Unit', price:Number(r.price)||0, description:r.description||'', minStock:Number(r.min_stock)||0 }),
