    rowsHTML += `<tr><td colspan="7" style="background:#eef1f5;font-weight:bold;padding:5px 6px;border:1px solid #999;">${String.fromCharCode(65+sIdx)}&nbsp;&nbsp;${esc((sec.name||'').replace(/^[A-Z]\.?\s*/,''))}</td></tr>`;
